// Lumière Skin Clinic: a deal for each booked/cancelled lead, and delete demo contacts older than 7 days (their deals go with them).
const plan = $('Plan run').first().json;
const C = {"location":"lX1GDRcqD985tKgOM4I3","pipeline":"e3YMhd6OJWtcGA9MFPnx","stage":"8530b169-8cdc-4a71-bfc7-165e969395a6"};
const G = 'https://services.leadconnectorhq.com';
const sent = $('Clinic: contacts').all().map(i => i.json);
const got = $('GHL clinic: save contacts').all().map(i => i.json);
const weekAgo = Date.now() - 7 * 864e5;
const reqs = [];
sent.forEach((s, i) => {
  const r = got[i] || {};
  if (s.kind === 'old' && r.statusCode === 200) {
    for (const old of r.body?.contacts || []) if (Date.parse(old.dateAdded) < weekAgo) reqs.push({ kind: 'delete', req: { method: 'DELETE', url: `${G}/contacts/${old.id}` } });
  }
  if (s.kind === 'contact' && r.statusCode < 300 && r.body?.contact) {
    const lead = plan.leads.clinic.find(l => l.id === s.leadId);
    if (lead.outcome === 'open') return;
    reqs.push({ kind: 'deal', contactId: r.body.contact.id, req: { method: 'POST', url: `${G}/opportunities/`, body: {
      locationId: C.location, pipelineId: C.pipeline, pipelineStageId: C.stage, contactId: r.body.contact.id,
      name: `${lead.firstName} ${lead.lastName} – consultation`, status: lead.outcome === 'converted' ? 'won' : 'lost', monetaryValue: lead.value } } });
  }
});
// ponytail: one harmless lookup so this list is never empty (n8n stops a branch with no items)
reqs.push({ kind: 'noop', req: { method: 'POST', url: `${G}/contacts/search`, body: { locationId: C.location, pageLimit: 1 } } });
return reqs.map(json => ({ json }));

// Northwind Home: a deal for each booked/cancelled lead, and delete demo contacts older than 7 days (their deals go with them).
const plan = $('Plan run').first().json;
const C = {"location":"VxYMePPrdwUBRt79Z4wC","pipeline":"F1gLtHkYfr2SF8ulCrzs","stage":"e5dc2f2e-3fdc-4e7d-af22-88009d9f79c3"};
const G = 'https://services.leadconnectorhq.com';
const sent = $('Store: contacts').all().map(i => i.json);
const got = $('GHL store: save contacts').all().map(i => i.json);
const weekAgo = Date.now() - 7 * 864e5;
const reqs = [];
sent.forEach((s, i) => {
  const r = got[i] || {};
  if (s.kind === 'old' && r.statusCode === 200) {
    for (const old of r.body?.contacts || []) if (Date.parse(old.dateAdded) < weekAgo) reqs.push({ kind: 'delete', req: { method: 'DELETE', url: `${G}/contacts/${old.id}` } });
  }
  if (s.kind === 'contact' && r.statusCode < 300 && r.body?.contact) {
